   932  static bool
   933  g10_parse_seckey(pgp_key_pkt_t *seckey,
   934                   const uint8_t *data,
   935                   size_t         data_len,
   936                   const char *   password)
   937  {
   938      s_exp_t          s_exp = {0};
   939      bool             ret = false;
   940      pgp_pubkey_alg_t alg = PGP_PKA_NOTHING;
   941      s_exp_t *        algorithm_s_exp = NULL;
   942      s_exp_block_t *  block = NULL;
   943      bool             is_protected = false;
   944
   945      RNP_DHEX("S-exp", (const uint8_t *) data, data_len);
   946
   947      const char *bytes = (const char *) data;
   948      if (!parse_sexp(&s_exp, &bytes, &data_len)) {
   949          goto done;
   950      }
   951
   952      /* expected format:
   953       *  (<type>
   954       *    (<algo>
   955       *     (x <mpi>)
   956       *     (y <mpi>)
   957       *    )
   958       *  )
   959       */
   960
   961      if (sub_element_count(&s_exp) != 2 || !sub_element_at(&s_exp, 0)->is_block ||
   962          sub_element_at(&s_exp, 1)->is_block) {
   963          RNP_LOG("Wrong format, expected: (<type> (...))");
   964          goto done;
   965      }
   966
   967      block = &sub_element_at(&s_exp, 0)->block;
   968      if (!strncmp("private-key", (const char *) block->bytes, block->len)) {
   969          is_protected = false;
   970      } else if (!strncmp("protected-private-key", (const char *) block->bytes, block->len)) {
   971          is_protected = true;
   972      } else {
   973          RNP_LOG("Unsupported top-level block: '%.*s'", (int) block->len, block->bytes);
   974          goto done;
   975      }
   976
   977      algorithm_s_exp = &sub_element_at(&s_exp, 1)->s_exp;
   978
   979      if (sub_element_count(algorithm_s_exp) < 2) {
   980          RNP_LOG("Wrong count of algorithm-level elements: %d, should great than 1",
   981                  (int) sub_element_count(algorithm_s_exp));
   982          goto done;
   983      }
   984
   985      if (!sub_element_at(algorithm_s_exp, 0)->is_block) {
   986          RNP_LOG("Expected block with algorithm name, but has s-exp");
   987          goto done;
   988      }
   989
   990      block = &sub_element_at(algorithm_s_exp, 0)->block;
   991      alg = PGP_PKA_NOTHING;
   992      for (size_t i = 0; i < ARRAY_SIZE(g10_alg_aliases); i++) {
   993          if (strlen(g10_alg_aliases[i].string) != block->len) {
   994              continue;
   995          }
   996          if (!memcmp(g10_alg_aliases[i].string, block->bytes, block->len)) {
   997              alg = (pgp_pubkey_alg_t) g10_alg_aliases[i].type;
   998              break;
   999          }
  1000      }
